443	////////////////////////////////////////////////////////////////////////////////////
444	// SegmentImpl implementation
445	////////////////////////////////////////////////////////////////////////////////////
446	
447	bool SegmentImpl::SegmentIndexFilter::is_filtered(uint64_t id) const {
448	  auto impl = impl_.lock();
449	  if (!impl) return false;
450	  auto result = impl->get_global_doc_id(id);
451	  if (!result.has_value()) {
452	    return false;
453	  }
454	  uint64_t doc_id = result.value();
455	  if (delete_store_ && delete_store_->is_deleted(doc_id)) {
456	    return true;
457	  }
458	  return false;
459	}
460	
461	Status SegmentImpl::Open(const SegmentOptions &options) {
462	  options_ = options;
463	  options_.enable_mmap_ = version_manager_->get_current_version().enable_mmap();
464	
465	  filter_ =
466	      std::make_shared<SegmentIndexFilter>(delete_store_, shared_from_this());
467	
468	  // load persist forward blocks
469	  auto s = load_persist_scalar_blocks();
470	  CHECK_RETURN_STATUS(s);
471	
472	  // load scalar indexes
473	  s = load_scalar_index_blocks();
474	  CHECK_RETURN_STATUS(s);
475	
476	  // load FTS indexes
477	  s = open_fts_indexers(false);
478	  CHECK_RETURN_STATUS(s);
479	
480	  // load vector indexes
481	  s = load_vector_index_blocks();
482	  CHECK_RETURN_STATUS(s);
483	
484	  auto writing_block = segment_meta_->writing_forward_block();
485	  if (!writing_block.has_value() && !options_.read_only_) {
486	    return Status::InternalError(
487	        "No writing block found when in writing mode.");
488	  }
489	
490	  if (writing_block.has_value()) {
491	    // init doc_id_allocator and block_id_allocator
492	    doc_id_allocator_ = writing_block.value().min_doc_id();
493	    BlockID max_block_id{writing_block.value().id()};
494	    for (auto &block : segment_meta_->persisted_blocks()) {
495	      max_block_id = std::max(max_block_id, block.id());
496	    }
497	    block_id_allocator_ = max_block_id + 1;
498	
499	    // recover writing block
500	    s = recover();
501	    CHECK_RETURN_STATUS(s);
502	  } else {
503	    // Update block_id_allocator_
504	    BlockID max_block_id{0};
505	    auto &persist_blocks = segment_meta_->persisted_blocks();
506	    for (const auto &block : persist_blocks) {
507	      max_block_id = std::max(max_block_id, block.id());
508	    }
509	    block_id_allocator_.store(max_block_id + 1);
510	  }
511	
512	  fresh_persist_block_offset();
513	
514	  fresh_persist_chunked_array();
515	
516	  return Status::OK();
517	}
518	
519	Status SegmentImpl::Create(const SegmentOptions &options, uint64_t min_doc_id) {
520	  options_ = options;
521	  filter_ =
522	      std::make_shared<SegmentIndexFilter>(delete_store_, shared_from_this());
523	
524	  // init memory forward block
525	  auto block_id = allocate_block_id();
526	  std::vector<std::string> columns{GLOBAL_DOC_ID, USER_ID};
527	  std::vector<std::string> schema_forward_fields =
528	      collection_schema_->forward_field_names();
529	  columns.insert(columns.end(), schema_forward_fields.begin(),
530	                 schema_forward_fields.end());
531	
532	  segment_meta_->set_writing_forward_block(
533	      {block_id, BlockType::SCALAR, min_doc_id, min_doc_id, 0, columns});
534	  auto vector_fields = collection_schema_->vector_fields();
535	  for (auto &field : vector_fields) {
536	    if (field->index_params()->type() == IndexType::FLAT) {
537	      segment_meta_->add_indexed_vector_field(field->name());
538	    }
539	  }
540	  auto s = load_scalar_index_blocks(true);
541	  CHECK_RETURN_STATUS(s);
542	
543	  s = open_fts_indexers(true);
544	  CHECK_RETURN_STATUS(s);
545	
546	  doc_id_allocator_.store(min_doc_id);
547	
548	  return Status::OK();
549	}
550	
551	Status SegmentImpl::close() {
552	  flush();
553	  if (invert_indexers_) {
554	    invert_indexers_.reset();
555	  }
556	  close_fts_indexers();
557	  for (const auto &[name, indexers] : vector_indexers_) {
558	    for (auto indexer : indexers) {
559	      indexer->Close();
560	    }
561	  }
562	  vector_indexers_.clear();
563	  for (const auto &[name, indexers] : quant_vector_indexers_) {
564	    for (auto indexer : indexers) {
565	      indexer->Close();
566	    }
567	  }
568	  quant_vector_indexers_.clear();
569	  for (auto [name, indexer] : memory_vector_indexers_) {
570	    indexer->Close();
571	  }
572	  memory_vector_indexers_.clear();
573	  for (auto [name, indexer] : quant_memory_vector_indexers_) {
574	    indexer->Close();
575	  }
576	  quant_memory_vector_indexers_.clear();
577	
578	  return Status::OK();
579	}
