26	namespace zvec {
27	
28	class Version {
29	 public:
30	  using Ptr = std::shared_ptr<Version>;
31	
32	  Version() = default;
33	
34	  static Status Load(const std::string &path, Version *version);
35	
36	  static Status Save(const std::string &path, const Version &version);
37	
38	 public:
39	  void set_schema(const CollectionSchema &schema) {
40	    schema_ = std::make_shared<CollectionSchema>(schema);
41	  }
42	
43	  const CollectionSchema &schema() const {
44	    return *schema_;
45	  }
46	
47	  void set_enable_mmap(bool enable_mmap) {
48	    enable_mmap_ = enable_mmap;
49	  }
50	
51	  bool enable_mmap() const {
52	    return enable_mmap_;
53	  }
54	
55	  Status add_persisted_segment_meta(const SegmentMeta::Ptr &meta) {
56	    if (meta == nullptr) {
57	      return Status::InvalidArgument("Segment meta is null");
58	    }
59	    auto iter = persisted_segment_metas_map_.find(meta->id());
60	    if (iter != persisted_segment_metas_map_.end()) {
61	      return Status::InvalidArgument("Segment meta already exists");
62	    }
63	    persisted_segment_metas_map_[meta->id()] = meta;
64	    return Status::OK();
65	  }
66	
67	  Status remove_persisted_segment_meta(SegmentID segment_id) {
68	    auto iter = persisted_segment_metas_map_.find(segment_id);
69	    if (iter == persisted_segment_metas_map_.end()) {
70	      return Status::NotFound("Segment meta not found");
71	    }
72	    persisted_segment_metas_map_.erase(segment_id);
73	    return Status::OK();
74	  }
75	
76	  Status update_persisted_segment_meta(SegmentMeta::Ptr meta) {
77	    if (meta == nullptr) {
78	      return Status::InvalidArgument("Segment meta is null");
79	    }
80	    auto iter = persisted_segment_metas_map_.find(meta->id());
81	    if (iter == persisted_segment_metas_map_.end()) {
82	      return Status::NotFound("Segment meta not found");
83	    }
84	    persisted_segment_metas_map_[meta->id()] =
85	        std::make_shared<SegmentMeta>(*meta);
86	    return Status::OK();
87	  }
88	
89	  void set_persisted_segment_metas(const std::vector<SegmentMeta::Ptr> &metas) {
90	    for (auto &meta : metas) {
91	      persisted_segment_metas_map_[meta->id()] = meta;
92	    }
93	  }
94	
95	  std::vector<SegmentMeta::Ptr> persisted_segment_metas() const {
96	    std::vector<SegmentMeta::Ptr> segment_metas;
97	    segment_metas.reserve(persisted_segment_metas_map_.size());
98	    for (auto &segment_meta : persisted_segment_metas_map_) {
99	      segment_metas.push_back(segment_meta.second);
100	    }
101	
102	    std::sort(segment_metas.begin(), segment_metas.end(),
103	              [](const SegmentMeta::Ptr &lhs, const SegmentMeta::Ptr &rhs) {
104	                return lhs->min_doc_id() < rhs->min_doc_id();
105	              });
106	
107	    return segment_metas;
108	  }
109	
110	  void reset_writing_segment_meta(SegmentMeta::Ptr segment_meta) {
111	    writing_segment_meta_ = segment_meta;
112	  }
113	
114	  SegmentMeta::Ptr writing_segment_meta() const {
115	    return writing_segment_meta_;
116	  }
117	
118	  void set_id_map_path_suffix(uint32_t suffix) {
119	    id_map_path_suffix_ = suffix;
120	  }
121	
122	  uint32_t id_map_path_suffix() const {
123	    return id_map_path_suffix_;
124	  }
125	
126	  void set_delete_snapshot_path_suffix(uint32_t suffix) {
127	    delete_snapshot_path_suffix_ = suffix;
128	  }
129	
130	  uint32_t delete_snapshot_path_suffix() const {
131	    return delete_snapshot_path_suffix_;
132	  }
133	
134	  void set_next_segment_id(SegmentID id) {
135	    next_segment_id_ = id;
136	  }
137	
138	  SegmentID next_segment_id() const {
139	    return next_segment_id_;
140	  }
141	
142	 public:
143	  bool operator==(const Version &other) const {
144	    if (*schema_ != *other.schema_ ||
145	        persisted_segment_metas_map_.size() !=
146	            other.persisted_segment_metas_map_.size()) {
147	      return false;
148	    }
149	
150	    for (const auto &item : persisted_segment_metas_map_) {
151	      auto it = other.persisted_segment_metas_map_.find(item.first);
152	      if (it == other.persisted_segment_metas_map_.end() ||
153	          *item.second != *it->second) {
154	        return false;
155	      }
156	    }
157	
158	    return true;
159	  }
160	
161	  std::string to_string() const;
162	
163	  std::string to_string_formatted(int indent_level = 0) const;
164	
165	 private:
166	  CollectionSchema::Ptr schema_;
167	  bool enable_mmap_{false};
168	
169	  std::unordered_map<SegmentID, SegmentMeta::Ptr> persisted_segment_metas_map_;
170	
171	  SegmentMeta::Ptr writing_segment_meta_;
172	
173	  uint32_t id_map_path_suffix_{0};
174	  uint32_t delete_snapshot_path_suffix_{0};
175	
176	  SegmentID next_segment_id_{0};
177	};
