2794	  bool emit_segment_row_id =
2795	      std::find(columns.begin(), columns.end(), LOCAL_ROW_ID) != columns.end();
2796	
2797	  for (size_t i = 0; i < scalar_blocks.size() && i < persist_stores_.size();
2798	       ++i) {
2799	    const auto &block = scalar_blocks[i];
2800	    const auto &store = persist_stores_[i];
2801	
2802	    std::vector<std::string> interested_cols;
2803	    for (const auto &col : columns) {
2804	      if (block.contain_column(col)) {
2805	        interested_cols.push_back(col);
2806	      }
2807	    }
2808	    if (interested_cols.empty() && emit_segment_row_id) {
2809	      interested_cols.push_back(GLOBAL_DOC_ID);
2810	    }
2811	
2812	    if (interested_cols.empty()) {
2813	      continue;
2814	    }
2815	
2816	    auto reader = store->scan(interested_cols);
2817	    if (!reader) {
2818	      continue;
2819	    }
2820	
2821	    auto key = std::make_pair(block.min_doc_id(), block.max_doc_id());
2822	    block_groups[key].push_back(std::move(reader));
2823	  }
2824	
2825	  if (memory_store_ && memory_store_->num_rows() > 0) {
2826	    std::vector<std::string> memory_scan_columns;
