2829	        memory_scan_columns.push_back(col);
2830	      }
2831	    }
2832	    if (memory_scan_columns.empty()) {
2833	      memory_scan_columns.push_back(GLOBAL_DOC_ID);
2834	    }
2835	    auto reader = memory_store_->scan(memory_scan_columns);
2836	    if (reader) {
2837	      auto &mem_block = segment_meta_->writing_forward_block().value();
2838	      auto key = std::make_pair(mem_block.min_doc_id(), mem_block.max_doc_id());
2839	      block_groups[key].push_back(std::move(reader));
2840	    }
2841	  }
2842	
2843	  std::vector<std::shared_ptr<arrow::Field>> fields;
2844	  for (const auto &col : columns) {
2845	    if (col == LOCAL_ROW_ID) {
2846	      continue;
2847	    } else if (col == GLOBAL_DOC_ID) {
2848	      fields.push_back(arrow::field(GLOBAL_DOC_ID, arrow::uint64(), false));
2849	    } else if (col == USER_ID) {
2850	      fields.push_back(arrow::field(USER_ID, arrow::utf8(), false));
