    DWORD wait_result = WaitForSingleObject(pi.hProcess, 0);
    if (wait_result == WAIT_TIMEOUT) {
      TerminateProcess(pi.hProcess, 1);
    }
  }

  WaitForSingleObject(pi.hProcess, INFINITE);

